    else:
        for i in range(len(seq)):
            if seq[i] == x:
                return i
            elif seq[i] <= x and seq[i + 1] > x:
                return i + 1

def search(x, seq):
    if seq == [] or seq == ():
        return 0
    if x < seq[0]:
        return 0
    elif x > seq[len(seq) - 1]:
        return len(seq)
    else:
        for i in range(len(seq)):
            if seq[i] == x:
                return i
            elif seq[i] <= x and seq[i + 1] > x:
                return i + 1
